import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';

/**
 * command-index.json is generated by kew/scripts/www_command_index.py from
 * the live command tree, and a kew test holds it equal to the CLI. The front
 * page no longer prints the command list, but the file is still committed
 * and public, so it must carry nothing of the machine that generated it.
 */
const RAW_INDEX = readFileSync(new URL('../src/lib/data/command-index.json', import.meta.url), 'utf8');
const INDEX = JSON.parse(RAW_INDEX);

/** Every string anywhere inside a JSON value. */
function strings(value) {
  if (typeof value === 'string') return [value];
  if (Array.isArray(value)) return value.flatMap(strings);
  if (value && typeof value === 'object') return Object.values(value).flatMap(strings);
  return [];
}

test('command-index.json carries no option defaults and no absolute path', () => {
  for (const entry of INDEX.commands) {
    for (const item of [...entry.arguments, ...entry.options]) {
      assert.ok(!('default' in item), `${entry.command} carries a default`);
    }
  }
  assert.doesNotMatch(RAW_INDEX, /"default"/);
  const absolute = strings(INDEX).filter((text) =>
    /(^|[\s"'(=`])(\/[\w.-]+\/|~\/|[A-Za-z]:\\)/.test(text)
  );
  assert.deepEqual(absolute, [], 'command-index.json carries an absolute path');
});
